from typing import List

class Fenwick:
    def __init__(self, n: int):
        self.n = n
        self.bit = [0] * (n + 1)

    def add(self, i: int, v: int) -> None:
        i += 1
        while i <= self.n:
            self.bit[i] += v
            i += i & -i

    def sum(self, i: int) -> int:
        # sum of indices [0, i)
        res = 0
        while i:
            res += self.bit[i]
            i -= i & -i
        return res

    def kth(self, k: int) -> int:
        # 1-indexed kth present element, returns 0-indexed position
        pos = 0
        step = 1 << (self.n.bit_length() - 1)
        while step:
            nxt = pos + step
            if nxt <= self.n and self.bit[nxt] < k:
                k -= self.bit[nxt]
                pos = nxt
            step >>= 1
        return pos

class Solution:
    def numberOfAlternatingGroups(self, colors: List[int], queries: List[List[int]]) -> List[int]:
        n = len(colors)
        bad = Fenwick(n)
        cnt = Fenwick(n)
        total_len = Fenwick(n)
        bad_count = 0

        def add_run(length: int, delta: int) -> None:
            if length > 0:
                cnt.add(length, delta)
                total_len.add(length, delta * length)

        def dist(a: int, b: int) -> int:
            return (b - a) % n

        initial = [i for i in range(n) if colors[i] == colors[(i + 1) % n]]
        bad_count = len(initial)
        for p in initial:
            bad.add(p, 1)

        if bad_count:
            for i, a in enumerate(initial):
                b = initial[(i + 1) % bad_count]
                add_run(dist(a, b) - 1, 1)

        def change_edge(p: int, make_bad: bool) -> None:
            nonlocal bad_count
            exists = bad.sum(p + 1) - bad.sum(p)

            if make_bad:
                if exists:
                    return
                if bad_count == 0:
                    add_run(n - 1, 1)
                else:
                    before = bad.sum(p + 1)
                    prev = bad.kth(before) if before else bad.kth(bad_count)
                    nxt = bad.kth(before + 1) if before < bad_count else bad.kth(1)
                    add_run(dist(prev, nxt) - 1, -1)
                    add_run(dist(prev, p) - 1, 1)
                    add_run(dist(p, nxt) - 1, 1)
                bad.add(p, 1)
                bad_count += 1
            else:
                if not exists:
                    return
                if bad_count == 1:
                    add_run(n - 1, -1)
                else:
                    before = bad.sum(p)
                    prev = bad.kth(before) if before else bad.kth(bad_count)
                    through = bad.sum(p + 1)
                    nxt = bad.kth(through + 1) if through < bad_count else bad.kth(1)
                    add_run(dist(prev, p) - 1, -1)
                    add_run(dist(p, nxt) - 1, -1)
                    add_run(dist(prev, nxt) - 1, 1)
                bad.add(p, -1)
                bad_count -= 1

        ans = []
        for q in queries:
            if q[0] == 1:
                k = q[1]
                if bad_count == 0:
                    ans.append(n)
                else:
                    t = k - 2
                    c = bad_count - cnt.sum(t + 1)
                    s = total_len.sum(n + 1) - total_len.sum(t + 1)
                    ans.append(s - t * c)
            else:
                _, i, color = q
                if colors[i] == color:
                    continue
                edges = [i, (i - 1) % n]
                old = [colors[p] == colors[(p + 1) % n] for p in edges]
                colors[i] = color
                for p, was_bad in zip(edges, old):
                    now_bad = colors[p] == colors[(p + 1) % n]
                    if was_bad != now_bad:
                        change_edge(p, now_bad)

        return ans
