import sys

def main():
    data = sys.stdin.read().split()
    idx = 0
    N = int(data[idx]); idx += 1
    M = int(data[idx]); idx += 1
    adj = [0] * N
    for _ in range(M):
        u = int(data[idx]); idx += 1
        v = int(data[idx]); idx += 1
        u -= 1
        v -= 1
        adj[u] |= (1 << v)
        adj[v] |= (1 << u)

    deg = [bin(adj[v]).count('1') for v in range(N)]

    # Build equations only for vertices with degree >= 1
    rows_list = [adj[v] for v in range(N) if deg[v] > 0]

    # Gaussian elimination over GF(2) to get RREF
    rank = 0
    pivot_cols = []
    for col in range(N):
        pivot_row = None
        for r in range(rank, len(rows_list)):
            if (rows_list[r] >> col) & 1:
                pivot_row = r
                break
        if pivot_row is None:
            continue
        rows_list[rank], rows_list[pivot_row] = rows_list[pivot_row], rows_list[rank]
        for r in range(len(rows_list)):
            if r != rank and ((rows_list[r] >> col) & 1):
                rows_list[r] ^= rows_list[rank]
        pivot_cols.append(col)
        rank += 1

    free_cols = [c for c in range(N) if c not in pivot_cols]

    # Build basis vectors of the null space
    basis = []
    for f in free_cols:
        vec = 1 << f
        for i in range(rank):
            row = rows_list[i]
            if (row >> f) & 1:
                vec |= (1 << pivot_cols[i])
        basis.append(vec)

    # Check that every vertex with degree >= 1 is covered by some basis vector
    ok = True
    for v in range(N):
        if deg[v] > 0:
            covered = False
            for vec in basis:
                if (vec >> v) & 1:
                    covered = True
                    break
            if not covered:
                ok = False
                break

    if not ok:
        print("No")
        return

    # Construct the integer values using each basis vector as a bit-plane
    x = [0] * N
    for i, vec in enumerate(basis):
        for v in range(N):
            if (vec >> v) & 1:
                x[v] |= (1 << i)

    # For any vertex that ended up with value 0 (must be isolated, degree 0),
    # set it to 1 which is always safe since it has no constraints.
    for v in range(N):
        if x[v] == 0:
            x[v] = 1

    print("Yes")
    print(' '.join(map(str, x)))


if __name__ == "__main__":
    main()
