import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    rows = [0] * n

    p = 2
    for _ in range(m):
        u = data[p] - 1
        v = data[p + 1] - 1
        p += 2
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    rank = 0
    pivots = []

    for col in range(n):
        pivot = -1
        for r in range(rank, n):
            if (rows[r] >> col) & 1:
                pivot = r
                break
        if pivot == -1:
            continue

        rows[rank], rows[pivot] = rows[pivot], rows[rank]
        for r in range(n):
            if r != rank and ((rows[r] >> col) & 1):
                rows[r] ^= rows[rank]

        pivots.append(col)
        rank += 1

    pivot_set = set(pivots)
    free = [c for c in range(n) if c not in pivot_set]

    ans = [0] * n
    for bit, f in enumerate(free):
        vec = 1 << f
        for r, pc in enumerate(pivots):
            if (rows[r] >> f) & 1:
                vec |= 1 << pc
        for v in range(n):
            if (vec >> v) & 1:
                ans[v] |= 1 << bit

    if any(x == 0 for x in ans):
        print("No")
    else:
        print("Yes")
        print(*ans)

if __name__ == "__main__":
    main()
